-- Add advanced CEFR levels across all three tables, then seed 18 C1 and 18 C2 exercises.
ALTER TABLE public.sentences DROP CONSTRAINT IF EXISTS sentences_level_check;
ALTER TABLE public.sentences ADD CONSTRAINT sentences_level_check CHECK (level IN ('A1','A2','B1','B2','C1','C2'));
ALTER TABLE public.practice_scores DROP CONSTRAINT IF EXISTS practice_scores_level_check;
ALTER TABLE public.practice_scores ADD CONSTRAINT practice_scores_level_check CHECK (level IN ('A1','A2','B1','B2','C1','C2'));
ALTER TABLE public.orthography_words DROP CONSTRAINT IF EXISTS orthography_words_level_check;
ALTER TABLE public.orthography_words ADD CONSTRAINT orthography_words_level_check CHECK (level IN ('A1','A2','B1','B2','C1','C2'));
ON CONFLICT (level, spanish_text) DO NOTHING;
